<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {message,Modal} from 'ant-design-vue';
import {support,sendSupportMutation,stateNames,type Ticket,type SupportPage,type SupportMessage} from '../api/modules/support';
import {useAuthStore} from '../stores/auth';
import {onBeforeRouteLeave} from 'vue-router';
const auth=useAuthStore();
const rows=ref<Ticket[]>([]), current=ref<Ticket|null>(null), messages=ref<SupportMessage[]>([]);
const q=ref(''),status=ref(''),unassigned=ref(false),newMessage=ref(false),cursor=ref<string|null>(null),busy=ref(false),sending=ref(false),error=ref('');
const ownerFilter=ref(''),assigneeFilter=ref(''),kindFilter=ref(''),versionFilter=ref(''),dateFrom=ref(''),dateTo=ref('');
const body=ref(''),visibility=ref('public'),operators=ref<{id:number;name:string}[]>([]),assignee=ref<number|null>(null),priority=ref('normal'),tags=ref('');
const attachments=ref<{id:string;name:string}[]>([]),uploading=ref(false),fileInput=ref<HTMLInputElement|null>(null);
const audit=ref<unknown[]>([]),templates=ref<string[]>([]);let selection=0,listGeneration=0;
const permits=(name:string)=>current.value?.allowed_actions.includes(name)??false;
const localDate=(v:string)=>new Date(v).toLocaleString();
const sourceNames:Record<string,string>={settings:'设置',help:'帮助文章',order:'印制订单',customization:'专属定制'};
const columns=[{title:'工单',key:'title'},{title:'用户',dataIndex:'owner_id'},{title:'状态',key:'status'},{title:'负责人',dataIndex:'assignee'},{title:'最近公开动态',key:'activity'},{title:'操作',key:'action'}];
async function load(more=false){const generation=++listGeneration;busy.value=true;error.value='';try{const r=await support.get<SupportPage<Ticket>>('tickets/',{q:q.value,status:status.value,owner_id:ownerFilter.value,assignee_id:assigneeFilter.value,kind:kindFilter.value,version:versionFilter.value,created_from:dateFrom.value,created_to:dateTo.value,unassigned:unassigned.value?'1':'',user_unread:newMessage.value?'1':'',cursor:more?cursor.value:''});if(generation!==listGeneration)return;rows.value=more?[...rows.value,...r.results]:r.results;cursor.value=r.next_cursor;}catch(e){if(generation===listGeneration)error.value=String(e);}finally{if(generation===listGeneration)busy.value=false;}}
onBeforeRouteLeave(()=>canLeave());
function canLeave(){return !sending.value&&!uploading.value&&(!body.value.trim()&&!attachments.value.length||window.confirm('回复尚未发送，确定离开当前工单？'));}
async function open(t:Ticket){if(!canLeave())return;const token=++selection;current.value=t;attachments.value=[];messages.value=[];audit.value=[];body.value='';visibility.value='public';error.value='';await refresh(token);}
async function refresh(token=selection){const id=current.value?.id;if(!id)return;try{const [detail,page]=await Promise.all([support.get<Ticket>(`tickets/${id}/`),support.get<SupportPage<SupportMessage>>(`tickets/${id}/messages/`,{limit:50})]);if(token!==selection)return;current.value=detail;messages.value=page.results;messageCursor.value=page.next_cursor;assignee.value=detail.assignee_id;priority.value=detail.priority;tags.value=detail.tags.join(',');await support.post(`tickets/${id}/read/`,{through_sequence:Math.max(0,...page.results.map(m=>m.sequence??0))});}catch(e){if(token===selection)error.value=String(e);}}
const messageCursor=ref<string|null>(null);
async function olderMessages(){const id=current.value?.id,token=selection;if(!id||!messageCursor.value)return;try{const p=await support.get<SupportPage<SupportMessage>>(`tickets/${id}/messages/`,{cursor:messageCursor.value,limit:50});if(token!==selection)return;messages.value.push(...p.results);messageCursor.value=p.next_cursor;await support.post(`tickets/${id}/read/`,{through_sequence:Math.max(0,...p.results.map(m=>m.sequence??0))});}catch(e){error.value=String(e);}}
async function mutate(endpoint:string,payload:Record<string,unknown>){const t=current.value;if(!t||sending.value)return;const token=selection;sending.value=true;try{await sendSupportMutation(auth.user!.id,t.id,endpoint,t.revision,payload);if(token===selection){body.value='';attachments.value=[];await refresh(token);await load();message.success('操作成功');}}catch(e){if(token===selection){error.value=String(e);await refresh(token);}}finally{sending.value=false;}}
function send(){if(!body.value.trim()&&!attachments.value.length)return;Modal.confirm({title:visibility.value==='internal'?'保存内部备注？':`公开回复工单 ${current.value?.number}？`,content:visibility.value==='internal'?'用户不会看到内部备注。':body.value,onOk:()=>mutate('messages',{body:body.value,visibility:visibility.value,attachments:attachments.value.map(a=>a.id)})});}
function act(action:string){const required=['request_info','resolve','close','reopen'].includes(action);if(required&&!body.value.trim()){message.warning('请先填写公开处理说明');return;}Modal.confirm({title:`确认${({accept:'受理',request_info:'要求补充',resolve:'提交答复',close:'关闭',reopen:'重开'} as Record<string,string>)[action]}工单 ${current.value?.number}？`,content:body.value,onOk:()=>mutate('actions',{action,body:body.value})});}
async function uploadFiles(event:Event){const files=Array.from((event.target as HTMLInputElement).files??[]);if(files.length+attachments.value.length>6){message.warning('最多 6 张截图');return;}uploading.value=true;const stamp=selection;try{for(const f of files){if(f.size>10_000_000||!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('截图限 JPEG、PNG、WebP，单张不超过 10 MB');const r=await support.post<{id:string;put_url:string;put_headers:Record<string,string>}>('uploads/',{mime:f.type,size:f.size});const u=new URL(r.put_url);if(u.protocol!=='https:'||!u.hostname.endsWith('.aliyuncs.com'))throw Error('上传地址无效');const headers={...r.put_headers};delete headers['Content-Length'];const result=await fetch(u,{method:'PUT',headers,body:f});if(!result.ok)throw Error('截图上传失败');await support.post(`uploads/${r.id}/complete/`,{});if(stamp===selection)attachments.value.push({id:r.id,name:f.name});}}catch(e){if(stamp===selection)error.value=String(e);}finally{uploading.value=false;(event.target as HTMLInputElement).value='';}}
async function attachment(id:string){try{const r=await support.get<{url:string}>(`attachments/${id}/url/`);const u=new URL(r.url);if(u.protocol!=='https:'||!u.hostname.endsWith('.aliyuncs.com'))throw Error('附件地址无效');window.open(u.href,'_blank','noopener,noreferrer');}catch(e){message.error(String(e));}}
async function audits(){const id=current.value?.id,token=selection;if(!id)return;try{const r=await support.get<SupportPage<unknown>>(`tickets/${id}/audit/`,{limit:50});if(token===selection)audit.value=r.results;}catch(e){error.value=String(e);}}
async function redact(m:SupportMessage){const reason=window.prompt('请填写隐藏此消息的原因（不能恢复原文）');if(!reason)return;await mutate('redactions',{message_id:m.id,reason});}
function close(){if(canLeave()){selection++;current.value=null;messages.value=[];body.value='';}}
onMounted(async()=>{await load();if(auth.hasPermission('support_center.assign_ticket')){try{operators.value=await support.get('operators/');}catch(e){error.value=String(e);}}if(auth.hasPermission('support_center.reply_ticket')){try{templates.value=await support.get<string[]>('reply-templates/');}catch{ /* configuration access is independent */ }}});
function leaving(e:BeforeUnloadEvent){if(body.value.trim()||attachments.value.length||sending.value||uploading.value){e.preventDefault();e.returnValue='';}}
window.addEventListener('beforeunload',leaving);onBeforeUnmount(()=>{selection++;listGeneration++;window.removeEventListener('beforeunload',leaving);});
</script>
<template>
 <div class="support-page">
  <h2>反馈工单</h2><a-space wrap><a-input v-model:value="q" placeholder="单号、标题或账号 ID" @press-enter="load()"/><a-select v-model:value="status" style="width:140px" @change="load()"><a-select-option value="">全部状态</a-select-option><a-select-option v-for="(name,code) in stateNames" :key="code" :value="code">{{name}}</a-select-option></a-select><a-checkbox v-model:checked="unassigned">未分派</a-checkbox><a-checkbox v-model:checked="newMessage">有用户新消息</a-checkbox><a-button @click="load()" :loading="busy">查询 / 刷新</a-button></a-space>
  <a-collapse style="margin-top:12px"><a-collapse-panel key="filters" header="更多筛选"><a-space wrap><a-input v-model:value="ownerFilter" placeholder="用户账号 ID"/><a-input v-model:value="assigneeFilter" placeholder="负责人 ID"/><a-input v-model:value="kindFilter" placeholder="问题类型 code"/><a-input v-model:value="versionFilter" placeholder="应用版本"/><label>创建日期从 <input v-model="dateFrom" type="date"/></label><label>到 <input v-model="dateTo" type="date"/></label></a-space></a-collapse-panel></a-collapse>
  <a-alert v-if="error" type="error" :message="error" show-icon style="margin:16px 0"/>
  <a-table :columns="columns" :data-source="rows" row-key="id" :loading="busy" :pagination="false" style="margin-top:16px"><template #bodyCell="{column,record}"><template v-if="column.key==='title'"><strong>{{record.title}}</strong><div>{{record.number}} <a-tag v-if="record.user_unread" color="orange">新消息</a-tag></div></template><a-tag v-if="column.key==='status'">{{stateNames[record.status]||record.status}}</a-tag><span v-if="column.key==='activity'">{{localDate(record.last_public_activity_at)}}</span><a-button v-if="column.key==='action'" @click="open(record)">查看</a-button></template></a-table><a-button v-if="cursor" @click="load(true)" :loading="busy">加载更多</a-button>
  <a-drawer :open="!!current" width="min(840px,95vw)" title="工单处理" :closable="!sending" :mask-closable="false" @close="close">
   <template v-if="current">
    <h3>{{current.number}} · {{current.title}}</h3><a-tag>{{stateNames[current.status]||current.status}}</a-tag><p>用户 {{current.owner_id}} · 联系方式 {{current.contact||'未填写'}} · 来源 {{sourceNames[current.source]||current.source}}</p><p>环境：{{current.environment}}</p><p v-if="current.related_id">关联{{current.related_type==='order'?'印制订单':'定制需求'}}：{{current.related_id}}（请在对应业务工作台核对，反馈操作不修改订单）</p>
    <a-space v-if="permits('assign')" wrap><a-select v-model:value="assignee" allow-clear placeholder="负责人" style="width:160px"><a-select-option v-for="o in operators" :key="o.id" :value="o.id">{{o.name}}</a-select-option></a-select><a-select v-model:value="priority" style="width:100px"><a-select-option value="low">低</a-select-option><a-select-option value="normal">普通</a-select-option><a-select-option value="high">高</a-select-option><a-select-option value="urgent">紧急</a-select-option></a-select><a-input v-model:value="tags" placeholder="标签，逗号分隔"/><a-button :loading="sending" @click="mutate('assign',{assignee_id:assignee??null,priority,tags:tags.split(',').map(x=>x.trim()).filter(Boolean)})">保存分派</a-button><a-button v-if="!current.assignee_id" :loading="sending" @click="mutate('assign',{assignee_id:auth.user?.id})">分配给我</a-button></a-space>
    <a-divider>沟通记录</a-divider>
    <article v-for="m in messages" :key="m.id" :class="['support-message',{internal:m.visibility==='internal'}]"><a-tag>{{m.visibility==='internal'?'内部备注':m.author_type==='staff'?'工作人员':'用户'}}</a-tag><small>{{localDate(m.created_at)}}</small><p>{{m.body}}</p><a-space wrap><a-button v-for="a in m.attachments" :key="a.id" @click="attachment(a.id)">查看截图</a-button><a-button v-if="permits('redact')&&!m.redacted" danger @click="redact(m)">隐藏敏感内容</a-button></a-space></article>
    <a-button v-if="messageCursor" @click="olderMessages">后续消息</a-button>
    <a-divider>处理操作</a-divider><a-radio-group v-model:value="visibility"><a-radio value="public">公开回复用户</a-radio><a-radio value="internal">内部备注</a-radio></a-radio-group>
    <a-select v-if="templates.length" placeholder="插入常用回复" style="width:100%;margin-top:12px" @change="(v:unknown)=>body=String(v)"><a-select-option v-for="t in templates" :key="t" :value="t">{{t}}</a-select-option></a-select>
    <a-textarea v-model:value="body" :maxlength="2000" :rows="5" :placeholder="visibility==='internal'?'内部记录，用户不可见':'公开回复或处理说明'" style="margin:12px 0" :disabled="sending"/>
    <input ref="fileInput" type="file" multiple accept="image/jpeg,image/png,image/webp" style="display:none" @change="uploadFiles"/><a-space wrap><a-button :loading="uploading" :disabled="sending||!permits(visibility==='internal'?'note':'reply')" @click="fileInput?.click()">附截图</a-button><a-tag v-for="asset in attachments" :key="asset.id" closable @close="attachments=attachments.filter(a=>a.id!==asset.id)">{{asset.name}}</a-tag></a-space><a-space wrap><a-button type="primary" :disabled="!permits(visibility==='internal'?'note':'reply')||(!body.trim()&&!attachments.length)||uploading" :loading="sending" @click="send">{{visibility==='internal'?'保存内部备注':'发送公开回复'}}</a-button><a-button v-for="action in ['accept','request_info','resolve','close','reopen']" v-show="permits(action)" :key="action" :disabled="sending" @click="act(action)">{{({accept:'受理',request_info:'要求补充',resolve:'答复完成',close:'关闭工单',reopen:'重新打开'} as Record<string,string>)[action]}}</a-button><a-button @click="refresh()">刷新详情</a-button><a-button @click="audits">查看审计</a-button></a-space>
    <pre v-if="audit.length" class="audit">{{JSON.stringify(audit,null,2)}}</pre>
   </template>
  </a-drawer>
 </div>
</template>
<style scoped>.support-page{padding:24px}.support-message{padding:16px;border:1px solid #e4e7ec;border-radius:10px;margin:12px 0}.support-message p{white-space:pre-wrap;overflow-wrap:anywhere}.internal{background:#fff8df;border-color:#eedb99}.audit{white-space:pre-wrap;font-size:12px;background:#f7f8fa;padding:12px}</style>
